1	"use server";
2	
3	/**
4	 * Archives a project and, optionally, its issues.
5	 *
6	 * Owner D. `archiveIssues` defaults to true: leaving live issues under an
7	 * archived project is the state that makes every "open issues" count wrong, so
8	 * opting out has to be deliberate.
9	 *
10	 * Must call (do not reimplement): archiveProjectSchema, can, assertNotArchived,
11	 * getActor, toActionResult
12	 */
13	
14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
15	import { withAction } from "@/actions/_lib/with-action";
16	import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
17	import { can } from "@/lib/permissions";
18	import { assertNotArchived } from "@/lib/soft-delete";
19	import { archiveProjectSchema, type ArchiveProjectInput } from "@/schemas/project";
20	import {
21	  archiveProject,
22	  listProjects,
23	} from "@/server/services/project-service";
24	import { ActionNotFoundError } from "@/actions/_lib/action-errors";
25	import type { ActionResult } from "@/types/api";
26	import type { Project } from "@/types/project";
27	
28	const run = withAction<typeof archiveProjectSchema, Project>(
29	  archiveProjectSchema,
30	  async (raw, actor) => {
31	    const input = raw as ArchiveProjectInput;
32	
33	    const page = await listProjects(actor, {
34	      orgId: input.orgId,
35	      limit: 100,
36	      includeArchived: true,
37	    });
38	    const current = page.items.find((row) => row.project.id === input.projectId);
39	    if (current === undefined) {
40	      throw new ActionNotFoundError(`project ${input.projectId}`);
41	    }
42	
43	    const allowed = can(actor, "project:archive", {
44	      kind: "project",
45	      orgId: input.orgId,
46	      projectId: input.projectId,
47	      visibility: current.project.visibility,
48	      leadId: current.project.leadId,
49	    });
50	    if (!allowed) {
51	      throw new ForbiddenActionError("project:archive");
52	    }
53	
54	    assertNotArchived("project", input.projectId, current.project);
55	
56	    const project = await archiveProject(actor, input);
57	    revalidateTagged(
58	      [orgTag(input.orgId), projectTag(project.id)],
59	      CACHE_PROFILES.minutes,
60	    );
61	    return project;
62	  },
63	  { revalidate: ["projects", "issues"], cacheProfile: "minutes" },
