/**
 * Guards shared by `createIssue`/`updateIssue`/`assignIssue`: every id a
 * caller hands in must resolve to something this org can actually see, or the
 * write is refused as not found — a cross-workspace id looks identical to a
 * nonexistent one because every lookup below is already `orgId`-scoped.
 */
async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<void> {
  if (!(await memberRepo.isActiveMember(orgId, userId))) {
    throw new NotFoundError("Member", userId);
  }
}

/** A parent must be a live issue of the same project — never archived, never borrowed from elsewhere. */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId || isArchived(parent)) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Every label id must belong to this org's own label set. */
async function requireOwnLabels(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const owned = new Set(
    (await labelRepo.listLabels(orgId)).map((label) => label.id),
  );
  for (const labelId of labelIds) {
    if (!owned.has(labelId)) {
      throw new NotFoundError("Label", labelId);
    }
  }
}

