/** A parent must be a live issue of the same project — never archived, never borrowed from elsewhere. */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId || isArchived(parent)) {
