function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * A reply's parent must be a live, top-level comment on the same issue — a
 * reply to a reply, a deleted comment, or a comment living under a different
 * issue (this org's or another's) is refused as not found.
 */
async function requireLiveTopLevelComment(
  orgId: OrgId,
  issueId: IssueId,
  parentId: NonNullable<CreateCommentInput["parentId"]>,
): Promise<void> {
  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (
    parent === null ||
    parent.issueId !== issueId ||
    parent.parentId !== null ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side, filtered down to this org's current,
 * active members. The composer's suggestions are taken from the same kind of
 * member list the server reads here, but a stale suggestion (someone who has
 * since left) must never survive to a notification — mentions of anyone else
 * are dropped rather than failing the comment write.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const candidates = [...new Set([...resolved, ...clientProvided])];

  const isMember = await Promise.all(
    candidates.map((userId) => memberRepo.isActiveMember(orgId, userId)),
  );
  return candidates.filter((_, index) => isMember[index]);
}

